package org.apache.commons.math3.linear;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.NonPositiveDefiniteMatrixException;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class RectangularCholeskyDecomposition_RectangularCholeskyDecomposition_TriageGen2Test {

    private static final double EPSILON = 1e-9;

    @Test
    public void testPositiveDefiniteMatrix() throws NonPositiveDefiniteMatrixException {
        // A standard 3x3 positive definite matrix
        double[][] data = {
            {4, 12, -16},
            {12, 37, -43},
            {-16, -43, 98}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        double small = 1e-10;

        RectangularCholeskyDecomposition decomposition = new RectangularCholeskyDecomposition(matrix, small);

        assertEquals(3, decomposition.getRank());
        RealMatrix root = decomposition.getRootMatrix();

        // Check if root * root^T = original matrix
        RealMatrix reconstruction = root.multiply(root.transpose());
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                assertEquals(matrix.getEntry(i, j), reconstruction.getEntry(i, j), EPSILON);
            }
        }
    }

    @Test
    public void testPositiveSemidefiniteMatrixWithRankDeficiency() throws NonPositiveDefiniteMatrixException {
        // A positive semi-definite matrix (rank 2)
        double[][] data = {
            {4, 2, 0},
            {2, 1, 0},
            {0, 0, 0}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        double small = 1e-10;

        RectangularCholeskyDecomposition decomposition = new RectangularCholeskyDecomposition(matrix, small);

        assertEquals(2, decomposition.getRank());
        RealMatrix root = decomposition.getRootMatrix();
        assertEquals(3, root.getRowDimension());
        assertEquals(2, root.getColumnDimension());

        RealMatrix reconstruction = root.multiply(root.transpose());
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                assertEquals(matrix.getEntry(i, j), reconstruction.getEntry(i, j), EPSILON);
            }
        }
    }

    @Test(expected = NonPositiveDefiniteMatrixException.class)
    public void testNonPositiveDefinite_FirstElement() throws NonPositiveDefiniteMatrixException {
        // Matrix where the largest diagonal element is < small
        double[][] data = {
            {1e-12, 0},
            {0, 1}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        double small = 1e-10;

        new RectangularCholeskyDecomposition(matrix, small);
    }

    @Test(expected = NonPositiveDefiniteMatrixException.class)
    public void testNonPositiveDefinite_NegativeElement() throws NonPositiveDefiniteMatrixException {
        // Matrix with a significantly negative diagonal element
        double[][] data = {
            {4, 2, 0},
            {2, 1, 0},
            {0, 0, -5}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        double small = 1e-10;

        new RectangularCholeskyDecomposition(matrix, small);
    }

    @Test
    public void testDiagonalSwapping() throws NonPositiveDefiniteMatrixException {
        // Matrix where the diagonal elements are not in order to trigger swap logic
        double[][] data = {
            {1, 0, 0},
            {0, 10, 0},
            {0, 0, 5}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        double small = 1e-10;

        RectangularCholeskyDecomposition decomposition = new RectangularCholeskyDecomposition(matrix, small);

        assertEquals(3, decomposition.getRank());
        RealMatrix reconstruction = decomposition.getRootMatrix().multiply(decomposition.getRootMatrix().transpose());
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                assertEquals(matrix.getEntry(i, j), reconstruction.getEntry(i, j), EPSILON);
            }
        }
    }

    @Test
    public void testSmallMatrix() throws NonPositiveDefiniteMatrixException {
        // 1x1 matrix
        double[][] data = {{9.0}};
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        double small = 1e-10;

        RectangularCholeskyDecomposition decomposition = new RectangularCholeskyDecomposition(matrix, small);

        assertEquals(1, decomposition.getRank());
        assertEquals(3.0, decomposition.getRootMatrix().getEntry(0, 0), EPSILON);
    }

    @Test
    public void testAllZeroMatrix() throws NonPositiveDefiniteMatrixException {
        double[][] data = {
            {0, 0},
            {0, 0}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        double small = 1e-10;

        RectangularCholeskyDecomposition decomposition = new RectangularCholeskyDecomposition(matrix, small);

        assertEquals(0, decomposition.getRank());
        assertEquals(2, decomposition.getRootMatrix().getRowDimension());
        assertEquals(0, decomposition.getRootMatrix().getColumnDimension());
    }
}
